stage_a_raw:
{
  "decisions": [
    {
      "decision": "frequency_domain",
      "evidence": "\"Each line, if selected, must operate between 2 and 10 trips per hour\"",
      "options": [
        "NonNegativeIntegers (integer trips per hour)",
        "NonNegativeReals (continuous trips per hour)"
      ],
      "plausibility": [
        0.55,
        0.45
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "capacity_per_trip_value",
      "evidence": "none (the text never states passengers carried per trip)",
      "options": [
        "capacity_per_trip = 20",
        "capacity_per_trip = 30",
        "capacity_per_trip = 1 (frequency itself is the capacity)"
      ],
      "plausibility": [
        0.4,
        0.35,
        0.25
      ],
      "majority_option": "capacity_per_trip = 20"
    },
    {
      "decision": "vehicle_usage_definition",
      "evidence": "\"The total number of vehicles available is 55, and the combined vehicle usage across all lines must not exceed this limit\"",
      "options": [
        "sum of frequencies f[i] <= 55",
        "sum of f[i] * y[i] <= 55 (only selected lines)",
        "sum of f[i] * some vehicle-per-trip factor <= 55"
      ],
      "plausibility": [
        0.5,
        0.3,
        0.2
      ],
      "majority_option": "sum of frequencies f[i] <= 55"
    },
    {
      "decision": "od_min_frequency_direction",
      "evidence": "\"ensuring that the total frequency of lines serving each OD pair meets a minimum threshold\"",
      "options": [
        "sum of serving frequencies >= min_od_frequency",
        "sum of serving frequencies >= demand (capacity must cover demand)",
        "sum of serving frequencies = min_od_frequency"
      ],
      "plausibility": [
        0.6,
        0.25,
        0.15
      ],
      "majority_option": "sum of serving frequencies >= min_od_frequency"
    },
    {
      "decision": "transfer_station_linkage",
      "evidence": "\"designating transfer stations only if at least two lines pass through them\"",
      "options": [
        "z[s] <= sum of y[i] over lines at s (transfer only if >=2 lines selected)",
        "z[s] <= (1/2) * sum of y[i] over lines at s",
        "z[s] free binary with no linking constraint"
      ],
      "plausibility": [
        0.5,
        0.3,
        0.2
      ],
      "majority_option": "z[s] <= sum of y[i] over lines at s (transfer only if >=2 lines selected)"
    },
    {
      "decision": "unsatisfied_demand_domain",
      "evidence": "\"penalty costs for any unsatisfied demand\"",
      "options": [
        "NonNegativeReals (fractional passengers allowed)",
        "NonNegativeIntegers (whole passengers)"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    }
  ]
}
